import { registrationTimeline } from "./registration-timeline";
import { formatAmount, type MemberDetails } from "./entity-details";

function isEarnings(name: string): boolean {
  const label = name.trim().replace(/\s+/gu, " ").toLowerCase();
  return (
    label === "employment" ||
    label === "employment and earnings" ||
    label === "employment and earnings - ad hoc payments" ||
    label === "employment and earnings - ongoing paid employment"
  );
}

export function formatPounds(amount: string | null): string {
  if (amount === null) return formatAmount(null);
  const unsigned = amount.replace(/^-/, "");
  const [whole, fraction = ""] = unsigned.split(".");
  return `${amount.startsWith("-") ? "−" : ""}£${formatAmount(`${whole}.${fraction.padEnd(2, "0")}`)}`;
}

export function summarizeMember(details: MemberDetails) {
  const pounds = details.summary.currencies.find(
    (group) => group.currency === "GBP",
  );
  const { months: earnings, undated } = registrationTimeline(
    details.declarations.filter((declaration) =>
      isEarnings(declaration.categoryName),
    ),
  );
  return {
    total: pounds?.amount ?? null,
    categories: pounds?.categories ?? [],
    earnings,
    undated,
  };
}
<script lang="ts">
  import { page } from "$app/state";
  import MemberDeclarations from "./MemberDeclarations.svelte";
  import RegistrationTimeline from "./RegistrationTimeline.svelte";
  import {
    categoryBars,
    memberHref,
    type MemberDetails,
  } from "./lib/entity-details";
  import { formatPounds, summarizeMember } from "./lib/member-summary";
  let {
    details,
    summary,
  }: { details: MemberDetails; summary: ReturnType<typeof summarizeMember> } =
    $props();
  const bars = $derived(categoryBars(summary.categories, "total"));
  const baseline = $derived(
    bars.reduce((total, bar) => total + (bar.negative ? bar.width : 0), 0),
  );
</script>

<div class="member-summary-top">
  <section class="member-breakdown" aria-labelledby="breakdown-heading">
    <h2 id="breakdown-heading">Declared value by category</h2>
    {#if summary.categories.length}
      <ul class="category-list" style:--baseline={`${baseline}%`}>
        {#each summary.categories as category, index}
          <li>
            <div class="category-label">
              <span>{category.categoryName}</span><span class="amount"
                >{formatPounds(category.amount)}</span
              >
            </div>
            <div class="signed-bar" aria-hidden="true">
              <span
                class:negative={bars[index].negative}
                style:width={`${bars[index].width}%`}
              ></span>
            </div>
            {#if category.unknownAmountCount}<p class="partial-note">
                Some amounts unavailable
              </p>{/if}
          </li>
        {/each}
      </ul>
    {:else}<p class="empty-details">No known declared values available.</p>{/if}
  </section>
  <RegistrationTimeline
    context="earnings"
    months={summary.earnings}
    undated={summary.undated}
  />
</div>
<section aria-labelledby="recent-declarations-heading">
  <div class="detail-section-heading">
    <h2 id="recent-declarations-heading">Recent declarations</h2>
  </div>
  {#if details.declarations.length}<MemberDeclarations
      declarations={details.declarations.slice(0, 5)}
    />{:else}<p class="empty-details">
      No declarations are stored for this MP.
    </p>{/if}
  <a
    class="text-button history-link"
    href={memberHref(details.member.id, "history", page.url.searchParams)}
    >View declaration history</a
  >
</section>
<script lang="ts">
  import { page } from "$app/state";
  import { formatPounds } from "./lib/member-summary";
  import Icon from "./lib/Icon.svelte";
  import { memberHref, type MemberProfile } from "./lib/entity-details";
  let {
    member,
    view,
    total,
  }: {
    member: MemberProfile;
    view: "summary" | "history";
    total: string | null;
  } = $props();
</script>

<header class="member-identity">
  <div class="member-identity-info">
    <div class="member-identity-title">
      <span class="profile-type"><Icon name="parliament" size={20} />MP</span>
      <h1>{member.name}</h1>
    </div>
    <p>
      {member.partyName || "Party unavailable"}<span
        >{member.membershipFrom || "Membership unavailable"}</span
      ><span>{member.isCurrentCommons ? "Current MP" : "Former MP"}</span>
    </p>
  </div>
  {#if view === "summary"}<div class="member-value">
      <span>Known declared value</span>
      <p class="member-total">{formatPounds(total)}</p>
    </div>{/if}
  <nav class="member-tabs" aria-label="Member views">
    <a
      href={memberHref(member.id, "summary", page.url.searchParams)}
      aria-current={view === "summary" ? "page" : undefined}>Summary</a
    >
    <a
      href={memberHref(member.id, "history", page.url.searchParams)}
      aria-current={view === "history" ? "page" : undefined}
      >Declaration history</a
    >
  </nav>
</header>
<script lang="ts">
  import { summarizeMember } from "./lib/member-summary";
  import MemberIdentity from "./MemberIdentity.svelte";
  import MemberSummary from "./MemberSummary.svelte";
  import MemberHistory from "./MemberHistory.svelte";
  import Icon from "./lib/Icon.svelte";
  import FunderIdentity from "./FunderIdentity.svelte";
  import FunderSummary from "./FunderSummary.svelte";
  import FunderHistory from "./FunderHistory.svelte";
  import { backToSearch, type DetailState } from "./lib/entity-details";
  import { page, navigating } from "$app/state";
  import { invalidate } from "$app/navigation";
  import type { PageModel } from "./lib/page";
  let { model }: { model: Extract<PageModel, { kind: "detail" }> } = $props();
  const route = $derived(model.route);
  let retrying = $state(false);
  async function retry() {
    retrying = true;
    try {
      await invalidate("exposed:page");
    } finally {
      retrying = false;
    }
  }
  const detailState = $derived<DetailState>(
    navigating.to || retrying ? { kind: "loading" } : model.result,
  );
  const backHref = $derived(backToSearch(page.url.searchParams));
</script>

<main
  id="details"
  class="detail-page"
  class:member-page={route.kind === "member"}
  class:funder-page={route.kind === "funder"}
  aria-busy={detailState.kind === "loading"}
>
  <a class="back-link" href={backHref}>Back to search</a>
  {#if detailState.kind === "loading"}
    <div class="detail-message" role="status">
      <span class="loading-indicator" aria-hidden="true"></span>
      <h1>Loading details</h1>
    </div>
  {:else if detailState.kind === "not-found"}
    <div class="detail-message">
      <h1>Entity not found</h1>
      <p>
        This MP or funder is not in the stored register. Search for another
        name.
      </p>
      <a class="text-button" href={backHref}>Search MPs and funders</a>
    </div>
  {:else if detailState.kind === "error"}
    <div class="detail-message" role="alert">
      <h1>Details couldn’t load</h1>
      <p>{detailState.message}</p>
      <button class="retry-button" onclick={retry}
        ><Icon name="retry" size={16} />Try again</button
      >
    </div>
  {:else if detailState.kind === "member"}
    {@const details = detailState.details}
    {@const summary = summarizeMember(details)}
    <MemberIdentity
      member={details.member}
      total={summary.total}
      view={route.kind === "member" ? route.view : "summary"}
    />
    {#if route.kind === "member" && route.view === "history"}<MemberHistory
        {details}
      />{:else}<MemberSummary {details} {summary} />{/if}
  {:else}
    {@const details = detailState.details}
    <FunderIdentity
      {details}
      view={route.kind === "funder" ? route.view : "summary"}
    />
    {#if route.kind === "funder" && route.view === "history"}
      <FunderHistory {details} />
    {:else}
      <FunderSummary {details} />
    {/if}
  {/if}
</main>
